L(OA, 7,
  "Aprenderé a analizar y evaluar un texto argumentativo completo, reuniendo tesis, evidencias, fallas, modalizadores, recursos y organización, y a transferir el análisis a un texto nuevo.",
  ["Conozco tesis, evidencias, fallas, modalizadores, recursos y organización.", "Sé expresar mi postura con razones."],
  ["Evaluar un texto argumentativo es revisar varios aspectos y juntar los resultados en un juicio. Primero, la tesis y su claridad. Luego, la información que la sostiene: ¿es pertinente y suficiente? Después, las fallas de argumentación, los recursos emocionales y los modalizadores. Por último, la organización, el léxico valorativo y las figuras retóricas.",
   "Un juicio crítico dice qué hace bien el texto y qué debe mejorar, con ejemplos tomados del propio texto. «Tiene una tesis clara y usa datos, pero generaliza a partir de un curso». Esa frase reúne un acierto y una debilidad, y cita la razón. Al revisar tu propio análisis, comprueba que cada afirmación tenga una cita o un ejemplo.",
   "Transferir significa aplicar lo aprendido a un texto nuevo, de otro género o tema. La columna de un diario, la carta de un vecino o el discurso de una candidata se evalúan con las mismas preguntas. Lo que cambia es el contexto: quién escribe, para quién y con qué intención. Adaptar el análisis a ese contexto también es parte de evaluar."],
  [("juicio crítico", "evaluación razonada con aciertos y debilidades"), ("transferir", "aplicar lo aprendido a una situación nueva"), ("género", "tipo de texto, como columna, carta, discurso o ensayo"), ("destinatario", "persona o grupo al que se dirige el texto"), ("síntesis", "resumen que reúne lo esencial")],
  [("Análisis completo de una carta",
    "Carta de ejemplo: «Señor director: el comedor del liceo tiene 20 mesas para 500 estudiantes. Es evidente que todo el sistema de alimentación es un desastre. Solicito que se amplíe el comedor». Evalúa tesis, evidencia, certeza y falla.",
    ["Tesis: se debe ampliar el comedor.", "Evidencia: 20 mesas para 500 estudiantes, pertinente.", "Certeza: «es evidente» y «todo el sistema… desastre» exageran lo que muestran los datos; hay una exageración."],
    "Tesis clara y dato pertinente; exagera al decir que todo el sistema es un desastre"),
   ("Transferencia a un discurso",
    "Discurso de ejemplo: «Compañeros: en el último año, 3 de 5 actividades del centro de estudiantes fueron suspendidas. ¿Vamos a seguir así? Voten por un equipo que cumpla». ¿Qué tesis, recurso y mejora hay?",
    ["Tesis implícita: hay que votar por un equipo que cumpla.", "Recurso: una pregunta retórica.", "El dato se podría respaldar diciendo de dónde proviene."],
    "Tesis: votar por un equipo que cumpla; recurso: pregunta retórica; mejora: citar la fuente del dato")],
  [("Evaluar solo si estoy de acuerdo.", "Un buen juicio considera la calidad del argumento.", "Evalúa cada aspecto con ejemplos del texto."),
   ("Comentar sin citar el texto.", "Una afirmación sin cita no se puede comprobar.", "Escribe la frase exacta que respalda tu juicio.")],
  ([E("¿Qué primer aspecto se revisa al evaluar un texto argumentativo: la tesis o la letra? Responde con una palabra.", "La tesis", "Sin ella no se sabe qué se defiende."),
    E("¿Un juicio crítico incluye solo defectos? Responde sí o no.", "No", "Incluye aciertos y debilidades."),
    E("Transferir un análisis es aplicarlo a ___. A) un texto nuevo B) el mismo texto", "A) un texto nuevo", "Mostrar que puedes usar lo aprendido en otro caso.")],
   [E("Columna de ejemplo: «Siempre hay ruido en la biblioteca; todos hablan. Propongo señalética de silencio». ¿Qué falla tiene? A) exageración con «siempre» y «todos» B) estereotipo sobre quienes usan la biblioteca", "A) exageración con «siempre» y «todos»", "Agranda el hecho sin cifras."),
    E("Carta de ejemplo: «Quizás convenga ampliar la ciclovía». ¿Qué grado de certeza muestra «quizás»? A) baja B) alta", "A) baja", "Presenta la propuesta como posibilidad."),
    E("Discurso de ejemplo: «No dejemos que el patio muera de sed». ¿Qué figura es «muera de sed»? A) personificación, porque el patio «muere» como un ser vivo B) antítesis, porque opone la vida y la muerte", "A) personificación, porque el patio «muere» como un ser vivo", "Atribuye al patio una cualidad de ser vivo.")],
   [E("Ensayo de ejemplo: «Mi vecino dice que las bicicletas deben ir por la calle. Pero lo multaron una vez por estacionar mal, así que su opinión no vale». ¿Qué falla hay? A) descalificación personal B) generalización apresurada", "A) descalificación personal", "Descarta la idea por la persona."),
    E("En un texto con introducción, tres razones y una conclusión con llamado a actuar, ¿cuántas partes de organización se pueden nombrar?", "3", "Introducción, desarrollo y conclusión."),
    E("Un autor afirma «sin duda, el calor ha subido» y cita un termómetro de su casa durante dos días. ¿Qué falla tiene su certeza? A) es mayor que la evidencia B) es menor que la evidencia", "A) es mayor que la evidencia", "Dos días en una casa no justifican «sin duda».")],
   [E("Un compañero dice: «Mi análisis es bueno porque mencioné cinco cosas», pero no citó el texto. ¿Qué le falta? A) citas o ejemplos del texto B) más adjetivos y figuras retóricas en cada afirmación", "A) citas o ejemplos del texto", "Cada afirmación debe poder comprobarse."),
    E("Dos juicios sobre la misma carta: (1) «Es mala». (2) «Tiene tesis clara, pero exagera con “todos”». ¿Cuál es un juicio crítico y por qué?", "El 2; porque señala un acierto y una debilidad con ejemplo", "El 1 no dice qué falla ni por qué.")],
   [E("Carta de ejemplo: «Estimados vecinos: quizás sea hora de mejorar la plaza. Según el municipio, la plaza tiene 12 bancas rotas. Ojalá nos escuchen». Evalúa: ¿qué palabra atenúa la propuesta y de dónde viene el dato de las bancas? Responde con el formato «palabra / fuente».", "quizás / el municipio", "«Quizás» atenúa la propuesta y «según el municipio» indica de dónde sale el dato."),
    E("Un columnista dice «Todos aman los días de lluvia» y aporta una anécdota. Escribe cómo mejorarías su afirmación con un modalizador. A) Muchas personas parecen disfrutar los días de lluvia B) Es indiscutible que todas las personas aman la lluvia", "A) Muchas personas parecen disfrutar los días de lluvia", "Ajusta la certeza a una evidencia pequeña.")]),
  [E("Discurso de ejemplo: «Compañeros: nuestro curso limpió el patio tres veces y las otras clases, ninguna. Sin duda, somos el único curso responsable». ¿Qué debilidad tiene? A) generaliza sobre los demás sin datos B) usa demasiados modalizadores de duda", "A) generaliza sobre los demás sin datos", "Concluye sobre todos los cursos con información incompleta.")],
  [E("¿Qué debe acompañar a cada afirmación de un análisis?", "Una cita o un ejemplo del texto", "Así se puede comprobar."),
   E("¿Se puede evaluar con las mismas preguntas una carta y un discurso? Responde sí o no.", "Sí", "Cambia el contexto, no los criterios."),
   E("¿Qué se revisa después de la tesis: la información que la sostiene o el tamaño de la letra?", "La información que la sostiene", "Es el siguiente paso del análisis.")],
  ("Lee esta columna de ejemplo: «Nuestras plazas están destruidas. El 90 % de los jóvenes de mi cuadra rayó una banca (dato de ejemplo, sin fuente). Es obvio que no les importa nada. Propongo multar a las familias». Escribe un juicio crítico de seis líneas que incluya: 1) la tesis, 2) una evidencia y su calidad, 3) una falla, 4) un modalizador y su efecto, 5) un acierto, 6) tu postura.",
   "Tesis: multar a las familias de quienes rayan. Evidencia: el 90 % de la cuadra, sin fuente ni muestra clara. Falla: generalización y estereotipo. Modalizador: «es obvio» da certeza excesiva. Acierto: la tesis está clara. Mi postura: refuto la multa; primero conviene ofrecer actividades y cuidar las bancas.",
   ["identifica la tesis", "evalúa la evidencia", "señala una falla y un modalizador", "incluye un acierto y su postura"], ["seis líneas"], ["no citar el texto", "olvidar el acierto"], "Comprueba que cada línea cite una frase del texto."),
  "Evalúa en tu cuaderno, con cinco preguntas, un texto de opinión que encuentres hoy.",
  "Escribe un juicio crítico de ocho líneas sobre un texto argumentativo distinto de los de este cuaderno y compáralo con el que hiciste aquí.")
